        return mutated_individual


    def simulated_annealing_acceptance(self, old_fitness, new_fitness):
        if new_fitness < old_fitness:
            return True
        else:
            acceptance_probability = np.exp((old_fitness - new_fitness) / self.temperature)
            return np.random.rand() < acceptance_probability


    def local_search(self, func, individual):
