    def __init__(self, budget=10000, dim=10, population_size=20, F=0.5, CR=0.3, initial_temperature=1.0, cooling_rate=0.95):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.F = F  # Differential weight
        self.CR = CR # Crossover probability
        self.initial_temperature = initial_temperature
        self.cooling_rate = cooling_rate
        self.temperature = initial_temperature
        self.remaining_budget = budget
        self.lb = -5.0
        self.ub = 5.0

    def initialize_population(self):
        return np.random.uniform(self.lb, self.ub, size=(self.population_size, self.dim))

    def evaluate_population(self, func, population):
        fitness = np.zeros(self.population_size)
        for i in range(self.population_size):
            fitness[i] = func(population[i])
            self.remaining_budget -= 1
            if self.remaining_budget <= 0:
                break
        return fitness

    def differential_mutation(self, population):
        mutated_population = np.copy(population)
        for i in range(self.population_size):
            # Randomly select three distinct individuals
            indices = np.random.choice(self.population_size, size=3, replace=False)
            x1, x2, x3 = population[indices]
            mutated_population[i] = x1 + self.F * (x2 - x3)  # Differential mutation
            mutated_population[i] = np.clip(mutated_population[i], self.lb, self.ub) # Clip to bounds
        return mutated_population

    def crossover(self, population, mutated_population):
        crossover_population = np.copy(population)
        for i in range(self.population_size):
            for j in range(self.dim):
                if np.random.rand() < self.CR:
                    crossover_population[i, j] = mutated_population[i, j]
        return crossover_population


    def accept_or_reject(self, func, candidate, current_solution, current_fitness):
        candidate_fitness = func(candidate)
        self.remaining_budget -= 1

        if candidate_fitness < current_fitness:
            return candidate, candidate_fitness
        else:
            delta = candidate_fitness - current_fitness
            acceptance_probability = np.exp(-delta / self.temperature)
            if np.random.rand() < acceptance_probability:
                return candidate, candidate_fitness
            else:
                return current_solution, current_fitness

    def __call__(self, func):
        population = self.initialize_population()
        fitness = self.evaluate_population(func, population)
        best_index = np.argmin(fitness)
        best_solution = population[best_index]
        best_fitness = fitness[best_index]

        while self.remaining_budget > 0:
            mutated_population = self.differential_mutation(population)
            offspring = self.crossover(population, mutated_population)
            offspring_fitness = self.evaluate_population(func, offspring)

            for i in range(self.population_size):
                offspring[i], offspring_fitness[i] = self.accept_or_reject(func, offspring[i], population[i], fitness[i])

            best_index_offspring = np.argmin(offspring_fitness)
            if offspring_fitness[best_index_offspring] < best_fitness:
                best_fitness = offspring_fitness[best_index_offspring]
                best_solution = offspring[best_index_offspring]

            population = offspring
            fitness = offspring_fitness

            self.temperature *= self.cooling_rate # Cool down the temperature

        return best_fitness, best_solution

